INSERT INTO "public"."framework_pack_versions" ("pack_key", "version_key", "title", "edition_date", "language", "source_url", "source_celex", "source_eli", "source_publication_date", "attribution", "review_evidence", "content_hash", "requirement_count", "imported_at", "source_kind", "edition_label", "distribution_rights", "rights_evidence", "review_owner", "approved_at", "owner_org_id") VALUES
	('custom.875dbf3a-109b-45a1-9b84-f5d80f76a621', 'v1', 'M10 Custom bd3dce02', '2026-09-25', 'en', NULL, NULL, NULL, NULL, 'Created by the organization', NULL, '468db281aadb1f659cd82cedb58471e3abc110e3563c981af61f4f7f76723dd1', 1, '2026-09-25 10:07:06.069053+00', 'customer_defined', NULL, NULL, NULL, NULL, NULL, '00000000-0000-4000-8000-0000000000ca'),
	('cra-annex-i', 'oj-2024-11-20-en', 'Cyber Resilience Act — Annex I essential cybersecurity requirements', '2024-11-20', 'en', 'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:32024R2847', '32024R2847', 'http://data.europa.eu/eli/reg/2024/2847/oj', '2024-11-20', '© European Union, 2024. Source: Official Journal of the European Union, OJ L, 20.11.2024, Regulation (EU) 2024/2847, Annex I, pp. 68–69. EUR-Lex.', 'Official Publications Office PDF https://op.europa.eu/o/opportal-service/download-handler?format=PDF&identifier=21b7d4eb-a6e2-11ef-85f0-01aa75ed71a1&language=en&productionSystem=cellar (SHA-256 e3ecaabddf6e321fa04097d15dfcccc7309d0fe5896240ab7625a27d74ab1b0a) pages 68-69 compared with pdftotext on 2026-09-24; EUR-Lex reuse terms checked.', '1a28baf6e6837b214223f9db5dbd88b20a5eecb87134877c406eab871fabd619', 25, '2026-09-24 05:57:34.935583+00', 'public_law', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "public"."framework_requirements" ("pack_key", "version_key", "requirement_key", "identifier", "parent_requirement_key", "position", "tree_order", "depth", "heading", "text", "source_reference", "owner_org_id") VALUES
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i', 'Annex I, Part I', NULL, 1, 1, 0, 'Part I Cybersecurity requirements relating to the properties of products with digital elements', 'Part I Cybersecurity requirements relating to the properties of products with digital elements', 'Annex I, Part I', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii', 'Annex I, Part II', NULL, 2, 17, 0, 'Part II Vulnerability handling requirements', 'Manufacturers of products with digital elements shall:', 'Annex I, Part II', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-1', 'Annex I, Part I, point (1)', 'annex-i-part-i', 1, 2, 1, 'Annex I, Part I, point (1)', 'Products with digital elements shall be designed, developed and produced in such a way that they ensure an appropriate level of cybersecurity based on the risks.', 'Annex I, Part I, point (1)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2', 'Annex I, Part I, point (2)', 'annex-i-part-i', 2, 3, 1, 'Annex I, Part I, point (2)', 'On the basis of the cybersecurity risk assessment referred to in Article 13(2) and where applicable, products with digital elements shall:', 'Annex I, Part I, point (2)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-1', 'Annex I, Part II, point (1)', 'annex-i-part-ii', 1, 18, 1, 'Annex I, Part II, point (1)', 'identify and document vulnerabilities and components contained in products with digital elements, including by drawing up a software bill of materials in a commonly used and machine-readable format covering at the very least the top-level dependencies of the products;', 'Annex I, Part II, point (1)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-2', 'Annex I, Part II, point (2)', 'annex-i-part-ii', 2, 19, 1, 'Annex I, Part II, point (2)', 'in relation to the risks posed to products with digital elements, address and remediate vulnerabilities without delay, including by providing security updates; where technically feasible, new security updates shall be provided separately from functionality updates;', 'Annex I, Part II, point (2)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-3', 'Annex I, Part II, point (3)', 'annex-i-part-ii', 3, 20, 1, 'Annex I, Part II, point (3)', 'apply effective and regular tests and reviews of the security of the product with digital elements;', 'Annex I, Part II, point (3)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-4', 'Annex I, Part II, point (4)', 'annex-i-part-ii', 4, 21, 1, 'Annex I, Part II, point (4)', 'once a security update has been made available, share and publicly disclose information about fixed vulnerabilities, including a description of the vulnerabilities, information allowing users to identify the product with digital elements affected, the impacts of the vulnerabilities, their severity and clear and accessible information helping users to remediate the vulnerabilities; in duly justified cases, where manufacturers consider the security risks of publication to outweigh the security benefits, they may delay making public information regarding a fixed vulnerability until after users have been given the possibility to apply the relevant patch;', 'Annex I, Part II, point (4)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-5', 'Annex I, Part II, point (5)', 'annex-i-part-ii', 5, 22, 1, 'Annex I, Part II, point (5)', 'put in place and enforce a policy on coordinated vulnerability disclosure;', 'Annex I, Part II, point (5)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-6', 'Annex I, Part II, point (6)', 'annex-i-part-ii', 6, 23, 1, 'Annex I, Part II, point (6)', 'take measures to facilitate the sharing of information about potential vulnerabilities in their product with digital elements as well as in third-party components contained in that product, including by providing a contact address for the reporting of the vulnerabilities discovered in the product with digital elements;', 'Annex I, Part II, point (6)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-7', 'Annex I, Part II, point (7)', 'annex-i-part-ii', 7, 24, 1, 'Annex I, Part II, point (7)', 'provide for mechanisms to securely distribute updates for products with digital elements to ensure that vulnerabilities are fixed or mitigated in a timely manner and, where applicable for security updates, in an automatic manner;', 'Annex I, Part II, point (7)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-ii-8', 'Annex I, Part II, point (8)', 'annex-i-part-ii', 8, 25, 1, 'Annex I, Part II, point (8)', 'ensure that, where security updates are available to address identified security issues, they are disseminated without delay and, unless otherwise agreed between a manufacturer and a business user in relation to a tailor-made product with digital elements, free of charge, accompanied by advisory messages providing users with the relevant information, including on potential action to be taken.', 'Annex I, Part II, point (8)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-a', 'Annex I, Part I, point (2)(a)', 'annex-i-part-i-2', 1, 4, 2, 'Annex I, Part I, point (2)(a)', 'be made available on the market without known exploitable vulnerabilities;', 'Annex I, Part I, point (2)(a)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-b', 'Annex I, Part I, point (2)(b)', 'annex-i-part-i-2', 2, 5, 2, 'Annex I, Part I, point (2)(b)', 'be made available on the market with a secure by default configuration, unless otherwise agreed between manufacturer and business user in relation to a tailor-made product with digital elements, including the possibility to reset the product to its original state;', 'Annex I, Part I, point (2)(b)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-c', 'Annex I, Part I, point (2)(c)', 'annex-i-part-i-2', 3, 6, 2, 'Annex I, Part I, point (2)(c)', 'ensure that vulnerabilities can be addressed through security updates, including, where applicable, through automatic security updates that are installed within an appropriate timeframe enabled as a default setting, with a clear and easy-to-use opt-out mechanism, through the notification of available updates to users, and the option to temporarily postpone them;', 'Annex I, Part I, point (2)(c)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-d', 'Annex I, Part I, point (2)(d)', 'annex-i-part-i-2', 4, 7, 2, 'Annex I, Part I, point (2)(d)', 'ensure protection from unauthorised access by appropriate control mechanisms, including but not limited to authentication, identity or access management systems, and report on possible unauthorised access;', 'Annex I, Part I, point (2)(d)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-e', 'Annex I, Part I, point (2)(e)', 'annex-i-part-i-2', 5, 8, 2, 'Annex I, Part I, point (2)(e)', 'protect the confidentiality of stored, transmitted or otherwise processed data, personal or other, such as by encrypting relevant data at rest or in transit by state of the art mechanisms, and by using other technical means;', 'Annex I, Part I, point (2)(e)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-f', 'Annex I, Part I, point (2)(f)', 'annex-i-part-i-2', 6, 9, 2, 'Annex I, Part I, point (2)(f)', 'protect the integrity of stored, transmitted or otherwise processed data, personal or other, commands, programs and configuration against any manipulation or modification not authorised by the user, and report on corruptions;', 'Annex I, Part I, point (2)(f)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-g', 'Annex I, Part I, point (2)(g)', 'annex-i-part-i-2', 7, 10, 2, 'Annex I, Part I, point (2)(g)', 'process only data, personal or other, that are adequate, relevant and limited to what is necessary in relation to the intended purpose of the product with digital elements (data minimisation);', 'Annex I, Part I, point (2)(g)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-h', 'Annex I, Part I, point (2)(h)', 'annex-i-part-i-2', 8, 11, 2, 'Annex I, Part I, point (2)(h)', 'protect the availability of essential and basic functions, also after an incident, including through resilience and mitigation measures against denial-of-service attacks;', 'Annex I, Part I, point (2)(h)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-i', 'Annex I, Part I, point (2)(i)', 'annex-i-part-i-2', 9, 12, 2, 'Annex I, Part I, point (2)(i)', 'minimise the negative impact by the products themselves or connected devices on the availability of services provided by other devices or networks;', 'Annex I, Part I, point (2)(i)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-j', 'Annex I, Part I, point (2)(j)', 'annex-i-part-i-2', 10, 13, 2, 'Annex I, Part I, point (2)(j)', 'be designed, developed and produced to limit attack surfaces, including external interfaces;', 'Annex I, Part I, point (2)(j)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-k', 'Annex I, Part I, point (2)(k)', 'annex-i-part-i-2', 11, 14, 2, 'Annex I, Part I, point (2)(k)', 'be designed, developed and produced to reduce the impact of an incident using appropriate exploitation mitigation mechanisms and techniques;', 'Annex I, Part I, point (2)(k)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-l', 'Annex I, Part I, point (2)(l)', 'annex-i-part-i-2', 12, 15, 2, 'Annex I, Part I, point (2)(l)', 'provide security related information by recording and monitoring relevant internal activity, including the access to or modification of data, services or functions, with an opt-out mechanism for the user;', 'Annex I, Part I, point (2)(l)', NULL),
	('cra-annex-i', 'oj-2024-11-20-en', 'annex-i-part-i-2-m', 'Annex I, Part I, point (2)(m)', 'annex-i-part-i-2', 13, 16, 2, 'Annex I, Part I, point (2)(m)', 'provide the possibility for users to securely and easily remove on a permanent basis all data and settings and, where such data can be transferred to other products or systems, ensure that this is done in a secure manner.', 'Annex I, Part I, point (2)(m)', NULL),
	('custom.875dbf3a-109b-45a1-9b84-f5d80f76a621', 'v1', 'control-1', 'INT-1', NULL, 1, 1, 0, 'Document design', 'Maintain a run-scoped operational control record.', 'Internal policy 1', '00000000-0000-4000-8000-0000000000ca');
